import re, json, math
LET='abcdefghijklmnopqrstuvwxy'
def parse(lines):
    """returns list of primitives: ('L',x1,y1,x2,y2,cls,ingroup) in units (x/2,y/4); ('T',col,row,text); others raw"""
    out=[]; ing=False
    for l in lines:
        s=l.strip()
        if s=='<g>': ing=True; continue
        if s=='</g>': ing=False; continue
        m=re.match(r'L\(([-\d.]+),([-\d.]+)->([-\d.]+),([-\d.]+)\)(\[.*\])?',s)
        if m:
            x1,y1,x2,y2=map(float,m.groups()[:4]); cls=(m.group(5) or '[solid]')[1:-1]
            out.append(('L',x1,y1,x2,y2,cls,ing)); continue
        m=re.match(r"T\(([-\d.]+),([-\d.]+),(.*)\)",s)
        if m:
            out.append(('T',(float(m.group(1))-2)/8,(float(m.group(2))-12)/16,eval(m.group(3)),ing)); continue
        out.append(('R',s,ing))
    return out
def pname(lx,ly):
    if abs(lx-round(lx))<1e-9 and abs(ly-round(ly))<1e-9 and 0<=round(lx)<=4 and 0<=round(ly)<=4:
        return LET[int(round(ly))*5+int(round(lx))]
    return f"({lx:g},{ly:g})"
def split_line(x1,y1,x2,y2):
    ts={0.0,1.0}
    dx=x2-x1; dy=y2-y1
    if dx!=0:
        for k in range(-10,40):
            t=(4*k-x1)/dx
            if 0<t<1: ts.add(t)
    if dy!=0:
        for k in range(-10,40):
            t=(4*k-y1)/dy
            if 0<t<1: ts.add(t)
    ts=sorted(ts); pieces=[]
    for a,b in zip(ts,ts[1:]):
        ax,ay=x1+dx*a,y1+dy*a; bx,by=x1+dx*b,y1+dy*b
        mx,my=(ax+bx)/2,(ay+by)/2
        cx,cy=math.floor(mx/4),math.floor(my/4)
        pieces.append(((cx,cy),(ax-4*cx,ay-4*cy),(bx-4*cx,by-4*cy)))
    if dx==0 and dy==0:
        cx,cy=math.floor(x1/4),math.floor(y1/4)
        if x1==4*cx and x1>0: pass
        pieces.append(((cx,cy),(x1-4*cx,y1-4*cy),(x1-4*cx,y1-4*cy)))
    return pieces
def percell(lines):
    prims=parse(lines)
    cells={}
    other=[]
    for p in prims:
        if p[0]=='L':
            _,x1,y1,x2,y2,cls,ing=p
            for cell,(ax,ay),(bx,by) in split_line(x1,y1,x2,y2):
                tag='' if cls=='solid' else ':'+cls.replace('solid ','')
                cells.setdefault(cell,[]).append(pname(ax,ay)+pname(bx,by)+tag)
        elif p[0]=='T':
            cells.setdefault((int(p[1]),int(p[2])),[]).append('T'+repr(p[3]))
        else:
            other.append(p[1])
    return cells,other
EOF
