use std::cmp::Ordering;

#[derive(Clone, Copy, Debug, PartialEq)]
pub struct Point {
    pub x: f32,
    pub y: f32,
}

impl Point {
    pub fn new(x: f32, y: f32) -> Self {
        Point { x, y }
    }
    pub fn add(&self, o: Point) -> Point {
        Point::new(self.x + o.x, self.y + o.y)
    }
    pub fn sub(&self, o: Point) -> Point {
        Point::new(self.x - o.x, self.y - o.y)
    }
    pub fn scale(&self, s: f32) -> Point {
        Point::new(self.x * s, self.y * s)
    }
    pub fn eq_approx(&self, o: &Point) -> bool {
        (self.x - o.x).abs() < 0.001 && (self.y - o.y).abs() < 0.001
    }
    pub fn distance(&self, o: &Point) -> f32 {
        ((self.x - o.x) * (self.x - o.x) + (self.y - o.y) * (self.y - o.y)).sqrt()
    }
}

pub fn fcmp(a: f32, b: f32) -> Ordering {
    if (a - b).abs() < 0.001 {
        Ordering::Equal
    } else if a < b {
        Ordering::Less
    } else {
        Ordering::Greater
    }
}

/// ordering of points: y first then x
pub fn pcmp(a: &Point, b: &Point) -> Ordering {
    match fcmp(a.y, b.y) {
        Ordering::Equal => fcmp(a.x, b.x),
        o => o,
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub struct Cell {
    pub x: i32,
    pub y: i32,
}

impl PartialOrd for Cell {
    fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
        Some(self.cmp(other))
    }
}
impl Ord for Cell {
    fn cmp(&self, other: &Self) -> Ordering {
        self.y.cmp(&other.y).then(self.x.cmp(&other.x))
    }
}

impl Cell {
    pub fn new(x: i32, y: i32) -> Self {
        Cell { x, y }
    }
    /// grid point within this cell; col 0..=4, row 0..=4
    pub fn p(&self, col: f32, row: f32) -> Point {
        Point::new(self.x as f32 + col * 0.25, self.y as f32 * 2.0 + row * 0.5)
    }
    pub fn origin(&self) -> Point {
        Point::new(self.x as f32, self.y as f32 * 2.0)
    }
    pub fn is_adjacent(&self, o: &Cell) -> bool {
        (self.x - o.x).abs() <= 1 && (self.y - o.y).abs() <= 1 && self != o
    }
    pub fn offset(&self, dx: i32, dy: i32) -> Cell {
        Cell::new(self.x + dx, self.y + dy)
    }
}
EOF
