    pub end_marker: Option<Marker>,
}

#[derive(Clone, Debug, PartialEq)]
pub struct Circle {
    pub center: Point,
    pub radius: f32,
    pub is_filled: bool,
}

#[derive(Clone, Debug, PartialEq)]
pub struct Arc {
    pub start: Point,
