#[derive(Clone, Debug, PartialEq)]
pub struct CellText {
    pub cell: Cell,
    pub content: String,
}

#[derive(Clone, Debug, PartialEq)]
pub enum Fragment {
    Line(Line),
    MarkerLine(MarkerLine),
    Circle(Circle),
    Arc(Arc),
    Polygon(Polygon),
    Rect(Rect),
    CellText(CellText),
}

pub fn line(a: Point, b: Point) -> Fragment {
    Fragment::Line(Line::new(a, b, false))
}
pub fn broken_line(a: Point, b: Point) -> Fragment {
    Fragment::Line(Line::new(a, b, true))
}
pub fn arc(a: Point, b: Point, r: f32) -> Fragment {
    Fragment::Arc(Arc { start: a, end: b, radius: r, major: false, sweep: false })
}
pub fn circle(c: Point, r: f32, filled: bool) -> Fragment {
    Fragment::Circle(Circle { center: c, radius: r, is_filled: filled })
}
pub fn polygon(pts: Vec<Point>, filled: bool) -> Fragment {
    Fragment::Polygon(Polygon { points: pts, is_filled: filled })
}
pub fn rect(a: Point, b: Point, filled: bool, broken: bool) -> Fragment {
    Fragment::Rect(Rect { start: a, end: b, is_filled: filled, radius: 0.0, is_broken: broken })
}

impl Line {
    pub fn new(a: Point, b: Point, is_broken: bool) -> Self {
        if pcmp(&a, &b) == Ordering::Greater {
            Line { start: b, end: a, is_broken }
        } else {
            Line { start: a, end: b, is_broken }
        }
    }
    pub fn new_noswap(a: Point, b: Point, is_broken: bool) -> Self {
        Line { start: a, end: b, is_broken }
    }
    pub fn is_horizontal(&self) -> bool {
        fcmp(self.start.y, self.end.y) == Ordering::Equal
    }
    pub fn is_vertical(&self) -> bool {
        fcmp(self.start.x, self.end.x) == Ordering::Equal
    }
    /// is point p on this line segment
    pub fn contains_point(&self, p: &Point) -> bool {
        let a = self.start;
        let b = self.end;
        let cross = (b.x - a.x) * (p.y - a.y) - (b.y - a.y) * (p.x - a.x);
        if cross.abs() > 0.001 {
            return false;
        }
        let minx = a.x.min(b.x) - 0.001;
        let maxx = a.x.max(b.x) + 0.001;
        let miny = a.y.min(b.y) - 0.001;
        let maxy = a.y.max(b.y) + 0.001;
        p.x >= minx && p.x <= maxx && p.y >= miny && p.y <= maxy
    }
    pub fn is_collinear_point(&self, p: &Point) -> bool {
        let a = self.start;
        let b = self.end;
        let cross = (b.x - a.x) * (p.y - a.y) - (b.y - a.y) * (p.x - a.x);
        cross.abs() < 0.001
    }
    pub fn is_degenerate(&self) -> bool {
        self.start.eq_approx(&self.end)
    }
    pub fn is_aligned(&self, o: &Line) -> bool {
        if self.is_degenerate() || o.is_degenerate() {
            return false;
        }
        self.is_collinear_point(&o.start) && self.is_collinear_point(&o.end)
    }
    pub fn is_touching(&self, o: &Line) -> bool {
        self.contains_point(&o.start)
            || self.contains_point(&o.end)
            || o.contains_point(&self.start)
            || o.contains_point(&self.end)
    }
    pub fn merge(&self, o: &Line) -> Option<Line> {
        if self.is_aligned(o) && self.is_touching(o) {
            let mut pts = vec![self.start, self.end, o.start, o.end];
            pts.sort_by(pcmp);
            Some(Line::new(pts[0], pts[3], self.is_broken || o.is_broken))
        } else {
            None
        }
    }
    /// heading based threshold
    fn threshold(&self) -> f32 {
        if self.is_horizontal() {
            1.0
        } else {
            1.5
        }
    }
    pub fn merge_circle(&self, c: &Circle) -> Option<MarkerLine> {
        let th = self.threshold();
        let d_end = self.end.distance(&c.center);
        let d_start = self.start.distance(&c.center);
        let close_end = d_end < th;
        let close_start = d_start < th;
        if c.radius <= 0.75 && (close_end || close_start) {
            let marker = if c.is_filled {
                Marker::Circle
            } else if c.radius >= 0.5 {
                Marker::BigOpenCircle
            } else {
                Marker::OpenCircle
            };
            let nl = if close_end {
                Line::new_noswap(self.start, c.center, self.is_broken)
            } else {
                Line::new_noswap(self.end, c.center, self.is_broken)
            };
            Some(MarkerLine { line: nl, start_marker: None, end_marker: Some(marker) })
        } else {
            None
        }
    }
}

impl Arc {
    pub fn endpoints(&self) -> [Point; 2] {
        [self.start, self.end]
    }
}

impl CellText {
    pub fn byte_len(&self) -> i32 {
        self.content.len() as i32
    }
}

impl Fragment {
    pub fn merge(&self, other: &Fragment) -> Option<Fragment> {
        match (self, other) {
            (Fragment::Line(a), Fragment::Line(b)) => a.merge(b).map(Fragment::Line),
            (Fragment::Line(a), Fragment::Circle(c)) => a.merge_circle(c).map(Fragment::MarkerLine),
            (Fragment::Circle(c), Fragment::Line(a)) => a.merge_circle(c).map(Fragment::MarkerLine),
            (Fragment::CellText(a), Fragment::CellText(b)) => {
                if a.cell.y == b.cell.y && a.cell.x + a.byte_len() == b.cell.x {
                    Some(Fragment::CellText(CellText { cell: a.cell, content: format!("{}{}", a.content, b.content) }))
                } else if a.cell.y == b.cell.y && b.cell.x + b.byte_len() == a.cell.x {
                    Some(Fragment::CellText(CellText { cell: b.cell, content: format!("{}{}", b.content, a.content) }))
                } else {
                    None
                }
            }
            _ => None,
        }
    }

    pub fn is_contacting(&self, other: &Fragment) -> bool {
        match (self, other) {
            (Fragment::Line(a), Fragment::Line(b)) => a.is_touching(b),
            (Fragment::Line(l), Fragment::Arc(a)) | (Fragment::Arc(a), Fragment::Line(l)) => {
                a.endpoints().iter().any(|p| l.contains_point(p))
            }
            (Fragment::Arc(a), Fragment::Arc(b)) => a
                .endpoints()
                .iter()
                .any(|p| b.endpoints().iter().any(|q| p.eq_approx(q))),
            (Fragment::CellText(a), Fragment::CellText(b)) => {
                a.cell.y == b.cell.y
                    && ((a.cell.x <= b.cell.x && a.cell.x + a.byte_len() >= b.cell.x)
                        || (b.cell.x <= a.cell.x && b.cell.x + b.byte_len() >= a.cell.x))
            }
            _ => false,
        }
    }
}
