use crate::fragment::*;
use crate::geom::Point;
use crate::settings::Settings;

pub fn escape_text(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    for ch in s.chars() {
        match ch {
            '&' => out.push_str("&amp;"),
            '<' => out.push_str("&lt;"),
            '>' => out.push_str("&gt;"),
            '"' => out.push_str("&quot;"),
            '\'' => out.push_str("&#39;"),
            c => out.push(c),
        }
    }
    out
}

fn n(v: f32) -> String {
    format!("{}", v)
}

pub struct Renderer<'a> {
    pub settings: &'a Settings,
}

impl<'a> Renderer<'a> {
    fn s(&self, v: f32) -> String {
        n(v * self.settings.scale)
    }
    fn pt(&self, p: &Point) -> String {
        format!("{},{}", self.s(p.x), self.s(p.y))
    }

    /// render a fragment with extra classes; in_group affects text rendering
    pub fn fragment(&self, f: &Fragment, extra_class: &[String], in_group: bool) -> String {
        let extra = if extra_class.is_empty() {
            String::new()
        } else {
            format!(" {}", extra_class.join(" "))
        };
        match f {
            Fragment::Line(l) => format!(
                "<line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\" class=\"{}{}\"></line>",
                self.s(l.start.x),
                self.s(l.start.y),
                self.s(l.end.x),
                self.s(l.end.y),
                if l.is_broken { "broken" } else { "solid" },
                extra
            ),
            Fragment::MarkerLine(m) => {
                let mut class = String::from(if m.line.is_broken { "broken" } else { "solid" });
                if let Some(sm) = m.start_marker {
                    class.push_str(&format!(" start_marked_{}", sm.name()));
                }
                if let Some(em) = m.end_marker {
                    class.push_str(&format!(" end_marked_{}", em.name()));
                }
                format!(
                    "<line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\" class=\"{}{}\"></line>",
                    self.s(m.line.start.x),
                    self.s(m.line.start.y),
                    self.s(m.line.end.x),
                    self.s(m.line.end.y),
                    class,
                    extra
                )
            }
            Fragment::Circle(c) => format!(
                "<circle cx=\"{}\" cy=\"{}\" r=\"{}\" class=\"{}{}\"></circle>",
                self.s(c.center.x),
                self.s(c.center.y),
                self.s(c.radius),
                if c.is_filled { "filled" } else { "nofill" },
                extra
            ),
            Fragment::Arc(a) => format!(
                "<path d=\"M {} A {},{} 0,{},{} {}\" class=\"nofill{}\"></path>",
                self.pt(&a.start),
                self.s(a.radius),
                self.s(a.radius),
                if a.major { 1 } else { 0 },
                if a.sweep { 1 } else { 0 },
                self.pt(&a.end),
                extra
            ),
            Fragment::Polygon(p) => {
                let pts: Vec<String> = p.points.iter().map(|pt| self.pt(pt)).collect();
                format!(
                    "<polygon points=\"{}\" class=\"{}{}\"></polygon>",
                    pts.join(" "),
                    if p.is_filled { "filled" } else { "nofill" },
                    extra
                )
            }
            Fragment::Rect(r) => {
                let x = r.start.x * self.settings.scale;
                let y = r.start.y * self.settings.scale;
                let w = r.end.x * self.settings.scale - x;
                let h = r.end.y * self.settings.scale - y;
                format!(
                    "<rect x=\"{}\" y=\"{}\" width=\"{}\" height=\"{}\" class=\"{} {}{}\" rx=\"{}\"></rect>",
                    n(x),
                    n(y),
                    n(w),
                    n(h),
                    if r.is_broken { "broken" } else { "solid" },
                    if r.is_filled { "filled" } else { "nofill" },
                    extra,
                    self.s(r.radius)
                )
            }
            Fragment::CellText(t) => {
                let x = t.cell.x as f32 + 0.25;
                let y = t.cell.y as f32 * 2.0 + 1.5;
                format!(
                    "<text x=\"{}\" y=\"{}\"{}>{}</text>",
                    self.s(x),
                    self.s(y),
                    if in_group { "" } else { " " },
                    escape_text(&t.content)
                )
            }
        }
    }
}

