    }
    pub fn map(&self) -> CellMap {
        self.cells.iter().cloned().collect()
    }
}

pub fn group_adjacents(map: &CellMap) -> Vec<Span> {
    let mut spans: Vec<Span> = vec![];
    for (cell, ch) in map.iter() {
        let mut found = false;
        for span in spans.iter_mut().rev() {
            if span.is_adjacent(cell) {
                span.cells.push((*cell, *ch));
                found = true;
                break;
            }
        }
        if !found {
            spans.push(Span::new(*cell, *ch));
        }
    }
    merge_spans_recursive(spans)
}

fn merge_spans_recursive(spans: Vec<Span>) -> Vec<Span> {
    let len = spans.len();
    let mut new_groups: Vec<Span> = vec![];
    for span in spans {
        let mut merged = false;
        for g in new_groups.iter_mut().rev() {
            if g.can_merge(&span) {
                g.cells.extend(span.cells.iter().cloned());
                merged = true;
                break;
            }
        }
        if !merged {
            new_groups.push(span);
        }
    }
    if new_groups.len() < len {
        merge_spans_recursive(new_groups)
    } else {
        new_groups
    }
}

pub fn merge_fragments_recursive(frags: Vec<Fragment>) -> Vec<Fragment> {
    let len = frags.len();
    let mut new_groups: Vec<Fragment> = vec![];
    for f in frags {
        let mut merged = false;
        for g in new_groups.iter_mut().rev() {
            if let Some(m) = g.merge(&f) {
                *g = m;
                merged = true;
                break;
            }
        }
        if !merged {
