        for g in groups.iter_mut().rev() {
            if g.iter().any(|gf| gf.is_contacting(&f)) {
                g.push(f.clone());
                found = true;
                break;
            }
        }
        if !found {
            groups.push(vec![f]);
        }
    }
    merge_groups_recursive(groups)
}

fn merge_groups_recursive(groups: Vec<Vec<Fragment>>) -> Vec<Vec<Fragment>> {
    let len = groups.len();
    let mut new_groups: Vec<Vec<Fragment>> = vec![];
    for grp in groups {
        let mut merged = false;
        for g in new_groups.iter_mut().rev() {
            if g.iter().any(|a| grp.iter().any(|b| a.is_contacting(b))) {
                g.extend(grp.iter().cloned());
                merged = true;
                break;
            }
        }
        if !merged {
            new_groups.push(grp);
        }
    }
    if new_groups.len() < len {
        merge_groups_recursive(new_groups)
    } else {
        new_groups
    }
}

/// compute fragments of the cells in the span, cells without fragments become cell text
pub fn span_fragments(map: &CellMap) -> Vec<Fragment> {
    let mut out = vec![];
    for (cell, ch) in map.iter() {
        let get = |dx: i32, dy: i32| -> char { *map.get(&cell.offset(dx, dy)).unwrap_or(&' ') };
        let nb = props::Neighbors {
            tl: get(-1, -1),
            t: get(0, -1),
            tr: get(1, -1),
            l: get(-1, 0),
            r: get(1, 0),
            bl: get(-1, 1),
            b: get(0, 1),
            br: get(1, 1),
        };
        let frags = props::fragments(*ch, &nb, *cell);
        if frags.is_empty() {
            out.push(Fragment::CellText(CellText { cell: *cell, content: ch.to_string() }));
        } else {
            out.extend(frags);
        }
    }
    out
}

pub struct Output {
    pub accepted: Vec<(Fragment, Vec<String>)>,
    pub rejects: Vec<Vec<Fragment>>,
}

pub fn to_svg(input: &str, settings: &Settings) -> String {
    let parsed = text_input::parse(input);
    let map = &parsed.cells;
    let (maxx, maxy) = if map.is_empty() {
        (0, 0)
    } else {
        (map.keys().map(|c| c.x).max().unwrap(), map.keys().map(|c| c.y).max().unwrap())
    };
    let w = settings.scale * (maxx + 2) as f32 * 1.0;
    let h = settings.scale * (maxy + 2) as f32 * 2.0;

    let spans = group_adjacents(map);
    let mut accepted: Vec<(Fragment, Vec<String>)> = vec![];
    let mut rejects: Vec<Vec<Fragment>> = vec![];
    for span in spans {
        let (acc, rej) = endorse::endorse_span(&span, &parsed);
        accepted.extend(acc);
        rejects.extend(rej);
    }
    let r = Renderer { settings };
    let mut out = svg::header(settings, w, h, &parsed.legend_css);
    for (f, classes) in accepted.iter() {
        out.push_str("  ");
        out.push_str(&r.fragment(f, classes, false));
        out.push('\n');
    }
    for g in rejects.iter().filter(|g| g.len() == 1) {
        out.push_str("  ");
        out.push_str(&r.fragment(&g[0], &[], false));
        out.push('\n');
    }
    for t in parsed.escaped.iter() {
        out.push_str("  ");
        out.push_str(&r.fragment(t, &[], false));
        out.push('\n');
    }
    for g in rejects.iter().filter(|g| g.len() > 1) {
        out.push_str("  <g>\n");
        for f in g {
            out.push_str("    ");
            out.push_str(&r.fragment(f, &[], true));
            out.push('\n');
        }
        out.push_str("  </g>\n");
    }
    out.push_str("</svg>");
    out
}
EOF
