use crate::circles;
use crate::fragment::*;
use crate::geom::{fcmp, pcmp, Point};
use crate::text_input::Parsed;
use std::cmp::Ordering;

fn feq(a: f32, b: f32) -> bool {
    fcmp(a, b) == Ordering::Equal
}

/// endorse a span: returns accepted fragments, and rejected contact groups
pub fn endorse_span(span: &Span, _parsed: &Parsed) -> (Vec<(Fragment, Vec<String>)>, Vec<Vec<Fragment>>) {
    let mut accepted: Vec<(Fragment, Vec<String>)> = vec![];
    let (circle_accepted, rest_map) = circles::endorse_circles_and_arcs(span);
    for f in circle_accepted {
        accepted.push((f, vec![]));
    }
    let frags = span_fragments(&rest_map);
    let merged = merge_fragments_recursive(frags);
    let groups = group_contacts(merged);
    let mut rejects = vec![];
    for g in groups {
        if let Some(r) = endorse_rect(&g) {
            accepted.push((r, vec![]));
        } else {
            rejects.push(g);
        }
    }
    (accepted, rejects)
}

fn as_lines(g: &[Fragment]) -> Option<Vec<Line>> {
    let mut v = vec![];
    for f in g {
        if let Fragment::Line(l) = f {
            v.push(l.clone());
        } else {
            return None;
        }
    }
    Some(v)
}

/// try to endorse 4 lines (or 4 lines + 4 arcs) as a rect
pub fn endorse_rect(g: &[Fragment]) -> Option<Fragment> {
    if g.len() == 4 {
        let lines = as_lines(g)?;
        return rect_from_lines(&lines, 0.0);
    }
    if g.len() == 8 {
        let mut lines = vec![];
        let mut arcs = vec![];
        for f in g {
            match f {
                Fragment::Line(l) => lines.push(l.clone()),
                Fragment::Arc(a) => arcs.push(a.clone()),
                _ => return None,
            }
        }
        if lines.len() != 4 || arcs.len() != 4 {
            return None;
        }
        let r = arcs[0].radius;
        if !arcs.iter().all(|a| feq(a.radius, r)) {
            return None;
        }
        let mut hs: Vec<&Line> = lines.iter().filter(|l| l.is_horizontal()).collect();
        let mut vs: Vec<&Line> = lines.iter().filter(|l| l.is_vertical()).collect();
        if hs.len() != 2 || vs.len() != 2 {
            return None;
        }
        hs.sort_by(|a, b| fcmp(a.start.y, b.start.y));
        vs.sort_by(|a, b| fcmp(a.start.x, b.start.x));
        let (top, bottom, left, right) = (hs[0], hs[1], vs[0], vs[1]);
        // check geometry
        let ok = feq(top.start.x, bottom.start.x)
            && feq(top.end.x, bottom.end.x)
            && feq(left.start.y, right.start.y)
            && feq(left.end.y, right.end.y)
            && feq(top.start.x, left.start.x + r)
            && feq(top.end.x, right.start.x - r)
            && feq(left.start.y, top.start.y + r)
            && feq(left.end.y, bottom.start.y - r);
        if !ok {
            return None;
        }
        // arcs must connect the corners
        let corners = [
            (top.start, left.start),
            (top.end, right.start),
            (bottom.start, left.end),
            (bottom.end, right.end),
        ];
        for (p, q) in corners.iter() {
            let found = arcs.iter().any(|a| {
                (a.start.eq_approx(p) && a.end.eq_approx(q)) || (a.start.eq_approx(q) && a.end.eq_approx(p))
            });
            if !found {
                return None;
            }
        }
        let is_broken = lines.iter().any(|l| l.is_broken);
        return Some(Fragment::Rect(Rect {
            start: Point::new(left.start.x, top.start.y),
            end: Point::new(right.start.x, bottom.start.y),
            is_filled: false,
            radius: r,
            is_broken,
        }));
    }
    None
}

fn rect_from_lines(lines: &[Line], _r: f32) -> Option<Fragment> {
    let mut hs: Vec<&Line> = lines.iter().filter(|l| l.is_horizontal() && !l.is_degenerate()).collect();
    let mut vs: Vec<&Line> = lines.iter().filter(|l| l.is_vertical() && !l.is_degenerate()).collect();
    if hs.len() != 2 || vs.len() != 2 {
        return None;
    }
    hs.sort_by(|a, b| fcmp(a.start.y, b.start.y));
    vs.sort_by(|a, b| fcmp(a.start.x, b.start.x));
    let (top, bottom, left, right) = (hs[0], hs[1], vs[0], vs[1]);
    let ok = top.start.eq_approx(&left.start)
        && top.end.eq_approx(&right.start)
        && bottom.start.eq_approx(&left.end)
        && bottom.end.eq_approx(&right.end);
    if !ok {
        return None;
    }
    let _ = pcmp;
    let is_broken = lines.iter().any(|l| l.is_broken);
    Some(Fragment::Rect(Rect {
        start: top.start,
        end: bottom.end,
        is_filled: false,
        radius: 0.0,
        is_broken,
    }))
}
