/// parse the legend, returns the css entries
fn parse_legend(s: &str) -> Option<Vec<(String, String)>> {
    let chars: Vec<char> = s.chars().collect();
    let title: Vec<char> = "# Legend:".chars().collect();
    if chars.len() < title.len() || chars[..title.len()] != title[..] {
        return None;
    }
    let mut p = title.len();
    while p < chars.len() && (chars[p] == ' ' || chars[p] == '\t') {
        p += 1;
    }
    if p < chars.len() && (chars[p] == '\n' || chars[p] == '\r') {
        p += 1;
    } else {
        return None;
    }
    if chars[p..].iter().all(|c| *c == '\n') {
        return None;
    }
    let mut entries = vec![];
    loop {
        // ident
        let st = p;
        while p < chars.len() && (chars[p].is_alphanumeric() || chars[p] == '_') {
            p += 1;
        }
        if p == st {
            break;
        }
        let name: String = chars[st..p].iter().collect();
        while p < chars.len() && (chars[p] == ' ' || chars[p] == '\t') {
            p += 1;
        }
        if p < chars.len() && chars[p] == '=' {
            p += 1;
        } else {
            break;
        }
        while p < chars.len() && (chars[p] == ' ' || chars[p] == '\t') {
            p += 1;
        }
        if p < chars.len() && chars[p] == '{' {
            p += 1;
        } else {
            break;
        }
        let cs = p;
        while p < chars.len() && chars[p] != '}' && chars[p] != '{' {
            p += 1;
        }
        if p < chars.len() && chars[p] == '}' {
            let content: String = chars[cs..p].iter().collect();
            p += 1;
            entries.push((name, content));
        } else {
            break;
        }
        if p < chars.len() && (chars[p] == '\n' || chars[p] == '\r') {
            p += 1;
        } else {
            break;
        }
    }
    Some(entries)
}

/// find escaped strings in a line; returns list of (byte_start, byte_end_exclusive, content)
fn find_escaped(line: &str) -> Vec<(usize, usize, String)> {
    let bytes: Vec<(usize, char)> = line.char_indices().collect();
    let mut res = vec![];
    let mut i = 0;
    while i < bytes.len() {
        if bytes[i].1 == '"' {
            // find closing
            let mut j = i + 1;
            let mut found = None;
            while j < bytes.len() {
                if bytes[j].1 == '\\' && j + 1 < bytes.len() && bytes[j + 1].1 == '"' {
                    j += 2;
                    continue;
                }
                if bytes[j].1 == '"' {
                    found = Some(j);
                    break;
                }
                j += 1;
            }
            if let Some(j) = found {
                let start = bytes[i].0;
                let end = bytes[j].0 + 1;
                let content = line[start + 1..end - 1].to_string();
                res.push((start, end, content));
                i = j + 1;
                continue;
            } else {
                break;
            }
        }
        i += 1;
    }
    res
}

pub fn parse(input: &str) -> Parsed {
    let mut legend_css = String::new();
    let mut text = input;
    if let Some(loc) = input.find("# Legend:") {
        if let Some(entries) = parse_legend(&input[loc..]) {
            text = &input[..loc];
            let v: Vec<String> = entries
                .iter()
                .map(|(n, c)| format!(".svgbob .{}{{ {} }}", n, c))
                .collect();
            legend_css = v.join("\n");
        }
    }
    let mut cells = CellMap::new();
    let mut escaped = vec![];
    for (y, line) in text.lines().enumerate() {
        let esc = find_escaped(line);
        let mut newline = String::with_capacity(line.len());
        let mut last = 0;
        for (s, e, content) in esc.iter() {
            // col of quote
            let col: usize = line[..*s].chars().map(|c| cell_count(c)).sum();
            escaped.push(Fragment::CellText(CellText {
                cell: Cell::new(col as i32, y as i32),
                content: content.clone(),
            }));
            newline.push_str(&line[last..*s]);
            for _ in *s..*e {
                newline.push(' ');
            }
            last = *e;
        }
        newline.push_str(&line[last..]);
        let mut x: i32 = 0;
        for ch in newline.chars() {
            if !ch.is_whitespace() {
                cells.insert(Cell::new(x, y as i32), ch);
            }
            x += cell_count(ch) as i32;
        }
    }
    Parsed { cells, legend_css, escaped }
}

fn cell_count(ch: char) -> usize {
    let w = char_width(ch);
    if w == 0 {
        1
    } else {
        w
    }
}
