use crate::fragment::*;
use crate::svg::Renderer;

#[derive(Clone, Debug)]
pub struct FragmentTree {
    pub fragment: Fragment,
    pub css_tags: Vec<String>,
    pub enclosing: Vec<FragmentTree>,
}

/// bounding box: (minx, miny, maxx, maxy)
pub fn bounds(f: &Fragment) -> (f32, f32, f32, f32) {
    match f {
        Fragment::Line(l) => (
            l.start.x.min(l.end.x),
            l.start.y.min(l.end.y),
            l.start.x.max(l.end.x),
            l.start.y.max(l.end.y),
        ),
        Fragment::MarkerLine(m) => bounds(&Fragment::Line(m.line.clone())),
        Fragment::Circle(c) => (
            c.center.x - c.radius,
            c.center.y - c.radius,
            c.center.x + c.radius,
            c.center.y + c.radius,
        ),
        Fragment::Arc(a) => (
            a.start.x.min(a.end.x),
            a.start.y.min(a.end.y),
            a.start.x.max(a.end.x),
            a.start.y.max(a.end.y),
        ),
        Fragment::Polygon(p) => {
            let minx = p.points.iter().map(|p| p.x).fold(f32::MAX, f32::min);
            let miny = p.points.iter().map(|p| p.y).fold(f32::MAX, f32::min);
            let maxx = p.points.iter().map(|p| p.x).fold(f32::MIN, f32::max);
            let maxy = p.points.iter().map(|p| p.y).fold(f32::MIN, f32::max);
            (minx, miny, maxx, maxy)
        }
        Fragment::Rect(r) => (r.start.x, r.start.y, r.end.x, r.end.y),
        Fragment::CellText(t) => {
            let x = t.cell.x as f32;
            let y = t.cell.y as f32 * 2.0;
            (x, y, x + t.content.chars().count() as f32, y + 2.0)
        }
    }
}

fn can_fit(container: &Fragment, other: &Fragment) -> bool {
    match container {
        Fragment::Rect(_) | Fragment::Circle(_) => {
            let (ax, ay, bx, by) = bounds(container);
            let (cx, cy, dx, dy) = bounds(other);
            ax <= cx && ay <= cy && bx >= dx && by >= dy
        }
        _ => false,
    }
}

pub fn css_tag(f: &Fragment) -> Option<String> {
    if let Fragment::CellText(t) = f {
        if t.content.starts_with('{') {
            if let Some(end) = t.content.find('}') {
                return Some(t.content[1..end].to_string());
            }
        }
    }
    None
}

impl FragmentTree {
    fn new(f: Fragment, tags: Vec<String>) -> Self {
        FragmentTree { fragment: f, css_tags: tags, enclosing: vec![] }
    }
    fn enclose(&mut self, other: &FragmentTree) -> bool {
        if can_fit(&self.fragment, &other.fragment) {
            self.enclosing.push(other.clone());
            true
        } else {
            false
        }
    }

    pub fn render(&self, r: &Renderer, out: &mut String) {
        let mut tags = self.css_tags.clone();
        for child in self.enclosing.iter() {
            if let Some(tag) = css_tag(&child.fragment) {
                tags.push(tag);
            }
        }
        out.push_str("  ");
        out.push_str(&r.fragment(&self.fragment, &tags, false));
        out.push('\n');
        for child in self.enclosing.iter() {
            if css_tag(&child.fragment).is_some() {
                continue;
            }
            child.render(r, out);
        }
    }
}

pub fn enclose_fragments(frags: Vec<(Fragment, Vec<String>)>) -> Vec<FragmentTree> {
    let trees: Vec<FragmentTree> = frags.into_iter().map(|(f, t)| FragmentTree::new(f, t)).collect();
    enclose_recursive(trees)
}

fn enclose_recursive(trees: Vec<FragmentTree>) -> Vec<FragmentTree> {
    let len = trees.len();
    let mut new_trees: Vec<FragmentTree> = vec![];
    for t in trees {
        let mut enclosed = false;
        for nt in new_trees.iter_mut().rev() {
            if nt.enclose(&t) {
                enclosed = true;
                break;
            }
        }
        if !enclosed {
            new_trees.push(t);
        }
    }
    if new_trees.len() < len {
        enclose_recursive(new_trees)
    } else {
        new_trees
    }
}
