            u: c.p(0.0, 4.0), v: c.p(1.0, 4.0), w: c.p(2.0, 4.0), x: c.p(3.0, 4.0), y: c.p(4.0, 4.0),
        }
    }
}

fn is(ch: char, set: &str) -> bool {
    set.contains(ch)
}

// neighbor predicate sets (ascii)
/// top neighbor that connects downward at w
fn conn_w(ch: char) -> bool {
    is(ch, "|+.*#:!│┼┬┌┐╷")
}
/// bottom neighbor that connects upward at c
fn conn_c(ch: char) -> bool {
    is(ch, "|+'`*#:!│┼┴└┘")
}
/// left neighbor connecting rightward at o
fn conn_o(ch: char) -> bool {
    is(ch, "-+.,'`*oO#~─┼├┬┴┌└")
}
/// right neighbor connecting leftward at k
fn conn_k(ch: char) -> bool {
    is(ch, "-+.,'`*oO#~─┼┤┬┴┐┘")
}
fn vert(ch: char) -> bool {
    is(ch, "|:!│")
}
fn horz(ch: char) -> bool {
    is(ch, "-~─")
}
fn bslash(ch: char) -> bool {
    is(ch, "\\X╲╳")
}
fn fslash(ch: char) -> bool {
    is(ch, "/X╱╳")
}

fn broken_if(ch: char, a: Point, b: Point) -> Fragment {
    let _ = ch;
    line(a, b)
}

pub fn fragments(ch: char, nb: &Neighbors, cell: Cell) -> Vec<Fragment> {
    if let Some(v) = unicode_fragments(ch, cell) {
        return v;
    }
    let p = Pts::new(cell);
    let unit = 0.25f32;
    let mut v = vec![];
    match ch {
        '-' => v.push(line(p.k, p.o)),
        '~' => v.push(broken_line(p.k, p.o)),
        '_' => v.push(line(p.u, p.y)),
        '=' => {
            v.push(line(cell.p(0.0, 1.5), cell.p(4.0, 1.5)));
            v.push(line(cell.p(0.0, 2.5), cell.p(4.0, 2.5)));
        }
        '|' => {
            if nb.tl == '\\' && nb.tr == '/' {
                v.push(line(p.a, p.m));
                v.push(line(p.e, p.m));
                v.push(line(p.m, p.w));
            } else if nb.tl == '\\' || nb.tr == '/' {
                // becomes text-like
            } else if nb.bl == '/' {
                v.push(line(p.c, p.m));
                v.push(line(p.m, p.u));
            } else if nb.br == '\\' {
                v.push(line(p.c, p.m));
                v.push(line(p.m, p.y));
            } else {
                v.push(line(p.c, p.w));
            }
            if nb.tl == '_' {
                v.push(line(p.a, p.c));
            }
            if nb.tr == '_' {
                v.push(line(p.c, p.e));
            }
            if horz(nb.l) {
                v.push(broken_if(nb.l, p.k, p.m));
            }
            if horz(nb.r) {
                v.push(broken_if(nb.r, p.m, p.o));
            }
            if nb.bl == 'X' {
                v.push(line(p.m, p.u));
            }
            if nb.br == 'X' {
                v.push(line(p.m, p.y));
            }
        }
        '/' => {
            if vert(nb.b) {
                v.push(line(p.e, p.m));
                v.push(line(p.m, p.w));
            } else {
                v.push(line(p.e, p.u));
            }
            if horz(nb.l) {
                v.push(line(p.k, p.m));
            }
            if horz(nb.r) {
                v.push(line(p.m, p.o));
            }
        }
        '\\' => {
            if nb.b == '|' {
                v.push(line(p.a, p.m));
                v.push(line(p.m, p.w));
            } else {
                v.push(line(p.a, p.y));
                if is(nb.b, "+`*#:!") {
                    v.push(line(p.m, p.w));
                }
            }
            if horz(nb.l) {
                v.push(line(p.k, p.m));
            }
            if horz(nb.r) {
                v.push(line(p.m, p.o));
            }
        }
        '+' => {
            if bslash(nb.tl) { v.push(line(p.a, p.m)); }
            if conn_w(nb.t) { v.push(line(p.c, p.m)); }
            if fslash(nb.tr) { v.push(line(p.e, p.m)); }
            if conn_o(nb.l) { v.push(line(p.k, p.m)); }
            if conn_k(nb.r) { v.push(line(p.m, p.o)); }
            if fslash(nb.bl) { v.push(line(p.m, p.u)); }
            if conn_c(nb.b) { v.push(line(p.m, p.w)); }
            if bslash(nb.br) { v.push(line(p.m, p.y)); }
        }
        'X' => {
            if bslash(nb.tl) { v.push(line(p.a, p.m)); }
            if vert(nb.t) { v.push(line(p.c, p.m)); }
            if fslash(nb.tr) { v.push(line(p.e, p.m)); }
            if horz(nb.l) { v.push(line(p.k, p.m)); }
            if horz(nb.r) { v.push(line(p.m, p.o)); }
            if fslash(nb.bl) { v.push(line(p.m, p.u)); }
            if vert(nb.b) { v.push(line(p.m, p.w)); }
            if bslash(nb.br) { v.push(line(p.m, p.y)); }
        }
        ':' | '!' => {
            if vert(nb.t) || vert(nb.b) {
                v.push(broken_line(p.c, p.w));
            }
        }
        '(' => {
            if conn_w(nb.t) {
            } else if conn_c(nb.b) {
