use crate::fragment::*;
use crate::geom::{Cell, Point};
use crate::unicode_map::unicode_fragments;

#[derive(Clone, Copy, Debug)]
pub struct Neighbors {
    pub tl: char,
    pub t: char,
    pub tr: char,
    pub l: char,
    pub r: char,
    pub bl: char,
    pub b: char,
    pub br: char,
}

#[allow(dead_code)]
pub struct Pts {
    pub a: Point, pub b: Point, pub c: Point, pub d: Point, pub e: Point,
    pub f: Point, pub g: Point, pub h: Point, pub i: Point, pub j: Point,
    pub k: Point, pub l: Point, pub m: Point, pub n: Point, pub o: Point,
    pub p: Point, pub q: Point, pub r: Point, pub s: Point, pub t: Point,
    pub u: Point, pub v: Point, pub w: Point, pub x: Point, pub y: Point,
}

impl Pts {
    pub fn new(c: Cell) -> Self {
        Pts {
            a: c.p(0.0, 0.0), b: c.p(1.0, 0.0), c: c.p(2.0, 0.0), d: c.p(3.0, 0.0), e: c.p(4.0, 0.0),
            f: c.p(0.0, 1.0), g: c.p(1.0, 1.0), h: c.p(2.0, 1.0), i: c.p(3.0, 1.0), j: c.p(4.0, 1.0),
            k: c.p(0.0, 2.0), l: c.p(1.0, 2.0), m: c.p(2.0, 2.0), n: c.p(3.0, 2.0), o: c.p(4.0, 2.0),
            p: c.p(0.0, 3.0), q: c.p(1.0, 3.0), r: c.p(2.0, 3.0), s: c.p(3.0, 3.0), t: c.p(4.0, 3.0),
            u: c.p(0.0, 4.0), v: c.p(1.0, 4.0), w: c.p(2.0, 4.0), x: c.p(3.0, 4.0), y: c.p(4.0, 4.0),
        }
    }
}

fn is(ch: char, set: &str) -> bool {
    set.contains(ch)
}

// neighbor predicate sets (ascii)
/// top neighbor that connects downward at w
fn conn_w(ch: char) -> bool {
    is(ch, "|+.*#:!│┼┬┌┐╷")
}
/// bottom neighbor that connects upward at c
fn conn_c(ch: char) -> bool {
    is(ch, "|+'`*#:!│┼┴└┘")
}
/// left neighbor connecting rightward at o
fn conn_o(ch: char) -> bool {
    is(ch, "-+.,'`*oO#~─┼├┬┴┌└")
}
/// right neighbor connecting leftward at k
fn conn_k(ch: char) -> bool {
    is(ch, "-+.,'`*oO#~─┼┤┬┴┐┘")
}
fn vert(ch: char) -> bool {
    is(ch, "|:!│")
}
fn horz(ch: char) -> bool {
    is(ch, "-~─")
}
fn bslash(ch: char) -> bool {
    is(ch, "\\X╲╳")
}
fn fslash(ch: char) -> bool {
    is(ch, "/X╱╳")
}

fn broken_if(ch: char, a: Point, b: Point) -> Fragment {
    let _ = ch;
    line(a, b)
}

pub fn fragments(ch: char, nb: &Neighbors, cell: Cell) -> Vec<Fragment> {
    if let Some(v) = unicode_fragments(ch, cell) {
        return v;
    }
    let p = Pts::new(cell);
    let unit = 0.25f32;
    let mut v = vec![];
    match ch {
        '-' => v.push(line(p.k, p.o)),
        '~' => v.push(broken_line(p.k, p.o)),
        '_' => v.push(line(p.u, p.y)),
        '=' => {
            v.push(line(cell.p(0.0, 1.5), cell.p(4.0, 1.5)));
            v.push(line(cell.p(0.0, 2.5), cell.p(4.0, 2.5)));
        }
        '|' => {
            if nb.tl == '\\' && nb.tr == '/' {
                v.push(line(p.a, p.m));
                v.push(line(p.e, p.m));
                v.push(line(p.m, p.w));
            } else if nb.tl == '\\' || nb.tr == '/' {
                // becomes text-like
            } else if nb.bl == '/' {
                v.push(line(p.c, p.m));
                v.push(line(p.m, p.u));
            } else if nb.br == '\\' {
                v.push(line(p.c, p.m));
                v.push(line(p.m, p.y));
            } else {
                v.push(line(p.c, p.w));
            }
            if nb.tl == '_' {
                v.push(line(p.a, p.c));
            }
            if nb.tr == '_' {
                v.push(line(p.c, p.e));
            }
            if horz(nb.l) {
                v.push(broken_if(nb.l, p.k, p.m));
            }
            if horz(nb.r) {
                v.push(broken_if(nb.r, p.m, p.o));
            }
            if nb.bl == 'X' {
                v.push(line(p.m, p.u));
            }
            if nb.br == 'X' {
                v.push(line(p.m, p.y));
            }
        }
        '/' => {
            if vert(nb.b) {
                v.push(line(p.e, p.m));
                v.push(line(p.m, p.w));
            } else {
                v.push(line(p.e, p.u));
            }
            if horz(nb.l) {
                v.push(line(p.k, p.m));
            }
            if horz(nb.r) {
                v.push(line(p.m, p.o));
            }
        }
        '\\' => {
            if nb.b == '|' {
                v.push(line(p.a, p.m));
                v.push(line(p.m, p.w));
            } else {
                v.push(line(p.a, p.y));
                if is(nb.b, "+`*#:!") {
                    v.push(line(p.m, p.w));
                }
            }
            if horz(nb.l) {
                v.push(line(p.k, p.m));
            }
            if horz(nb.r) {
                v.push(line(p.m, p.o));
            }
        }
        '+' => {
            if bslash(nb.tl) { v.push(line(p.a, p.m)); }
            if conn_w(nb.t) { v.push(line(p.c, p.m)); }
            if fslash(nb.tr) { v.push(line(p.e, p.m)); }
            if conn_o(nb.l) { v.push(line(p.k, p.m)); }
            if conn_k(nb.r) { v.push(line(p.m, p.o)); }
            if fslash(nb.bl) { v.push(line(p.m, p.u)); }
            if conn_c(nb.b) { v.push(line(p.m, p.w)); }
            if bslash(nb.br) { v.push(line(p.m, p.y)); }
        }
        'X' => {
            if bslash(nb.tl) { v.push(line(p.a, p.m)); }
            if vert(nb.t) { v.push(line(p.c, p.m)); }
            if fslash(nb.tr) { v.push(line(p.e, p.m)); }
            if horz(nb.l) { v.push(line(p.k, p.m)); }
            if horz(nb.r) { v.push(line(p.m, p.o)); }
            if fslash(nb.bl) { v.push(line(p.m, p.u)); }
            if vert(nb.b) { v.push(line(p.m, p.w)); }
            if bslash(nb.br) { v.push(line(p.m, p.y)); }
        }
        ':' | '!' => {
            if vert(nb.t) || vert(nb.b) {
                v.push(broken_line(p.c, p.w));
            }
        }
        '(' => {
            if conn_w(nb.t) {
            } else if conn_c(nb.b) {
                v.push(arc_s(p.c, p.w, unit * 6.0, false));
            } else {
                v.push(arc_s(p.e, p.y, unit * 8.0, false));
            }
        }
        ')' => {
            if conn_w(nb.t) || conn_c(nb.b) {
            } else {
                v.push(arc_s(p.a, p.u, unit * 8.0, true));
            }
        }
        '*' | 'o' | 'O' => {
            let c = match ch {
                '*' => circle(p.m, unit, true),
                'o' => circle(p.m, unit, false),
                _ => circle(p.m, unit * 2.0, false),
            };
            let mut lines = vec![];
            let mut has_circle = false;
            if bslash(nb.tl) { has_circle = true; }
            if vert(nb.t) { has_circle = true; }
            if fslash(nb.tr) { has_circle = true; }
            if horz(nb.l) {
                has_circle = true;
                if ch == '*' { lines.push(line(p.k, p.m)); }
            } else if ch == '*' && is(nb.l, "+*oO#") {
                lines.push(line(p.k, p.m));
            }
            if horz(nb.r) {
                has_circle = true;
                if ch == '*' { lines.push(line(p.m, p.o)); }
            } else if ch == '*' && is(nb.r, "+*oO#") {
                lines.push(line(p.m, p.o));
            }
            if fslash(nb.bl) { has_circle = true; lines.push(line(p.q, p.u)); }
            if vert(nb.b) { has_circle = true; lines.push(line(p.r, p.w)); }
            if bslash(nb.br) { has_circle = true; lines.push(line(p.s, p.y)); }
            if has_circle {
                v.push(c);
            }
            v.extend(lines);
        }
        '#' => {
            let mut lines = vec![];
            let mut has = false;
            let mut diag = false;
            if conn_w(nb.t) || nb.t == '#' { has = true; lines.push(line(p.c, p.h)); }
            if is(nb.l, "-+*oO~#") { has = true; }
            if is(nb.r, "-+*oO~#") { has = true; }
            if conn_c(nb.b) || nb.b == '#' { has = true; lines.push(line(p.r, p.w)); }
            if bslash(nb.tl) { diag = true; lines.push(line(p.a, p.g)); }
            if fslash(nb.tr) { diag = true; lines.push(line(p.e, p.i)); }
            if fslash(nb.bl) { diag = true; lines.push(line(p.q, p.u)); }
            if bslash(nb.br) { diag = true; lines.push(line(p.s, p.y)); }
            if diag && !has {
                let o = cell.origin();
                v.push(polygon(
                    vec![
                        Point::new(o.x + 0.85, o.y + 1.5),
                        Point::new(o.x + 0.85, o.y + 0.5),
                        Point::new(o.x + 0.15, o.y + 0.5),
                        Point::new(o.x + 0.15, o.y + 1.5),
                    ],
                    true,
                ));
            } else if has || diag {
                v.push(rect(p.f, p.t, true, false));
            }
            v.extend(lines);
        }
        '<' => {
            if is(nb.r, "-+.'*oO#<~") {
                v.push(polygon(vec![p.j, p.k, p.t], true));
            } else if is(nb.l, "-+*oO#~") {
                v.push(line(p.j, p.k));
                v.push(line(p.k, p.t));
            }
        }
        '>' => {
            if is(nb.l, "-+.`*oO#>~") {
                v.push(polygon(vec![p.f, p.o, p.p], true));
            } else if is(nb.r, "-+*oO#~") {
                v.push(line(p.f, p.o));
                v.push(line(p.o, p.p));
            }
        }
        '^' => {
            if conn_c(nb.b) {
                v.push(polygon(vec![p.p, p.c, p.t], true));
                v.push(line(p.r, p.w));
            } else if conn_w(nb.t) {
                v.push(line(p.c, p.u));
                v.push(line(p.c, p.y));
            } else if fslash(nb.bl) {
                v.push(polygon(vec![cell.p(-0.5, 3.0), cell.p(3.0, 1.0), cell.p(3.0, 3.75)], true));
                v.push(line(p.q, p.u));
            } else if bslash(nb.br) {
                v.push(polygon(vec![cell.p(4.5, 3.0), cell.p(1.0, 1.0), cell.p(1.0, 3.75)], true));
                v.push(line(p.s, p.y));
            }
        }
        'v' | 'V' => {
            if conn_w(nb.t) {
                v.push(line(p.c, p.h));
                v.push(polygon(vec![p.f, p.j, p.w], true));
            } else if conn_c(nb.b) {
                v.push(line(p.a, p.w));
                v.push(line(p.e, p.w));
            } else if bslash(nb.tl) {
                v.push(line(p.a, p.g));
                v.push(polygon(vec![cell.p(-0.5, 1.0), cell.p(3.0, 3.0), cell.p(3.0, 0.25)], true));
            } else if fslash(nb.tr) {
                v.push(line(p.e, p.i));
                v.push(polygon(vec![cell.p(4.5, 1.0), cell.p(1.0, 3.0), cell.p(1.0, 0.25)], true));
            } else if nb.tl == '.' {
                v.push(polygon(vec![p.f, p.o, p.c], true));
            } else if nb.tr == '.' {
                v.push(polygon(vec![p.j, p.k, p.c], true));
            }
        }
        '.' => {
            if vert(nb.b) {
                v.push(line(p.r, p.w));
            }
        }
        _ => {}
    }
    v
}

fn arc_s(a: Point, b: Point, r: f32, sweep: bool) -> Fragment {
    Fragment::Arc(Arc { start: a, end: b, radius: r, major: false, sweep })
}
