#[derive(Clone)]
pub struct Shape {
    /// localized cells
    cells: Vec<(Cell, char)>,
    /// fragment relative to localized origin (0,0)
    fragment: Fragment,
}

pub struct Shapes {
    circles: Vec<Shape>,
    three_quarters: Vec<Shape>,
    halves: Vec<Shape>,
    quarters: Vec<Shape>,
}

fn art_cells(art: &str) -> Vec<(Cell, char)> {
    let mut v = vec![];
    for (y, line) in art.lines().enumerate() {
        for (x, ch) in line.chars().enumerate() {
            if !ch.is_whitespace() {
                v.push((Cell::new(x as i32, y as i32), ch));
            }
        }
    }
    v
}

fn localize(cells: &[(Cell, char)]) -> (Vec<(Cell, char)>, i32, i32) {
    let minx = cells.iter().map(|(c, _)| c.x).min().unwrap_or(0);
    let miny = cells.iter().map(|(c, _)| c.y).min().unwrap_or(0);
    (
        cells.iter().map(|(c, ch)| (Cell::new(c.x - minx, c.y - miny), *ch)).collect(),
        minx,
        miny,
    )
}

fn arc_frag(start: Point, end: Point, r: f32, major: bool, sweep: bool, ox: i32, oy: i32) -> Fragment {
    let off = Point::new(ox as f32, oy as f32 * 2.0);
    Fragment::Arc(Arc { start: start.sub(off), end: end.sub(off), radius: r, major, sweep })
}

fn build() -> Shapes {
    let mut circles = vec![];
    let mut three_quarters = vec![];
    let mut halves = vec![];
    let mut quarters = vec![];
    for a in ARTS {
        let cells = art_cells(a.art);
        circles.push(Shape {
            cells: cells.clone(),
            fragment: Fragment::Circle(Circle { center: Point::new(a.cx, a.cy), radius: a.r, is_filled: false }),
        });
        if a.r < 2.0 {
            continue;
        }
        let is_left = |c: &Cell| c.x as f32 + 0.5 <= a.cx;
        let is_right = |c: &Cell| c.x as f32 + 0.5 >= a.cx;
        let is_top = |c: &Cell| c.y as f32 * 2.0 + 1.0 <= a.cy;
        let is_bottom = |c: &Cell| c.y as f32 * 2.0 + 1.0 >= a.cy;
        let tl: Vec<(Cell, char)> = cells.iter().filter(|(c, _)| is_left(c) && is_top(c)).cloned().collect();
        let tr: Vec<(Cell, char)> = cells.iter().filter(|(c, _)| is_right(c) && is_top(c)).cloned().collect();
        let bl: Vec<(Cell, char)> = cells.iter().filter(|(c, _)| is_left(c) && is_bottom(c)).cloned().collect();
        let br: Vec<(Cell, char)> = cells.iter().filter(|(c, _)| is_right(c) && is_bottom(c)).cloned().collect();
        let center = Point::new(a.cx, a.cy);
        let top = Point::new(a.cx, a.cy - a.r);
        let bottom = Point::new(a.cx, a.cy + a.r);
        let left = Point::new(a.cx - a.r, a.cy);
        let right = Point::new(a.cx + a.r, a.cy);
        let _ = center;
        let union = |sets: &[&Vec<(Cell, char)>]| -> Vec<(Cell, char)> {
            let mut v: Vec<(Cell, char)> = vec![];
            for (c, ch) in cells.iter() {
                if sets.iter().any(|s| s.iter().any(|(cc, _)| cc == c)) {
                    v.push((*c, *ch));
                }
            }
            v
        };
        let mut mk = |set: Vec<(Cell, char)>, s: Point, e: Point, major: bool, sweep: bool| -> Shape {
            let (loc, ox, oy) = localize(&set);
            Shape { cells: loc, fragment: arc_frag(s, e, a.r, major, sweep, ox, oy) }
        };
        // three quarters: missing one quadrant
        three_quarters.push(mk(union(&[&tr, &bl, &br]), top, left, true, true));
        three_quarters.push(mk(union(&[&tl, &bl, &br]), top, right, true, false));
        three_quarters.push(mk(union(&[&tl, &tr, &br]), left, bottom, true, true));
        three_quarters.push(mk(union(&[&tl, &tr, &bl]), right, bottom, true, false));
        // halves
        halves.push(mk(union(&[&tl, &tr]), left, right, false, true));
        halves.push(mk(union(&[&bl, &br]), left, right, false, false));
        halves.push(mk(union(&[&tl, &bl]), top, bottom, false, false));
        halves.push(mk(union(&[&tr, &br]), top, bottom, false, true));
        // quarters
        quarters.push(mk(tl.clone(), top, left, false, false));
        quarters.push(mk(tr.clone(), top, right, false, true));
        quarters.push(mk(bl.clone(), left, bottom, false, false));
        quarters.push(mk(br.clone(), right, bottom, false, true));
    }
    Shapes { circles, three_quarters, halves, quarters }
}

fn shapes() -> &'static Shapes {
    static S: OnceLock<Shapes> = OnceLock::new();
    S.get_or_init(build)
}

fn translate(f: &Fragment, ox: i32, oy: i32) -> Fragment {
    let off = Point::new(ox as f32, oy as f32 * 2.0);
    match f {
        Fragment::Circle(c) => Fragment::Circle(Circle { center: c.center.add(off), radius: c.radius, is_filled: c.is_filled }),
        Fragment::Arc(a) => Fragment::Arc(Arc {
            start: a.start.add(off),
            end: a.end.add(off),
            radius: a.radius,
            major: a.major,
            sweep: a.sweep,
        }),
        _ => f.clone(),
    }
}

fn try_match(list: &[Shape], map: &CellMap) -> Option<(Fragment, CellMap)> {
    if map.is_empty() {
        return None;
    }
    let minx = map.keys().map(|c| c.x).min().unwrap();
    let miny = map.keys().map(|c| c.y).min().unwrap();
    for shape in list.iter().rev() {
        let ok = shape.cells.iter().all(|(c, ch)| map.get(&Cell::new(c.x + minx, c.y + miny)) == Some(ch));
        if ok {
            let mut rest = map.clone();
            for (c, _) in shape.cells.iter() {
                rest.remove(&Cell::new(c.x + minx, c.y + miny));
            }
            return Some((translate(&shape.fragment, minx, miny), rest));
        }
    }
    None
}

/// try to match circles and arcs in the span; returns accepted fragments and remaining cells
pub fn endorse_circles_and_arcs(span: &Span) -> (Vec<Fragment>, CellMap) {
    let s = shapes();
    let mut map = span.map();
    let mut accepted = vec![];
    loop {
        let m = try_match(&s.circles, &map)
            .or_else(|| try_match(&s.three_quarters, &map))
            .or_else(|| try_match(&s.halves, &map))
            .or_else(|| try_match(&s.quarters, &map));
        match m {
            Some((f, rest)) => {
                accepted.push(f);
                map = rest;
            }
            None => break,
        }
    }
    (accepted, map)
}
