/// compute fragments of the cells in the span, cells without fragments become cell text
pub fn span_fragments(map: &CellMap) -> Vec<FSpan> {
    let mut out = vec![];
    for (cell, ch) in map.iter() {
        let get = |dx: i32, dy: i32| -> char { *map.get(&cell.offset(dx, dy)).unwrap_or(&' ') };
        let nb = props::Neighbors {
            tl: get(-1, -1),
            t: get(0, -1),
            tr: get(1, -1),
            l: get(-1, 0),
            r: get(1, 0),
            bl: get(-1, 1),
            b: get(0, 1),
            br: get(1, 1),
        };
        let frags = props::fragments(*ch, &nb, *cell);
        if frags.is_empty() {
            out.push(FSpan { frag: Fragment::CellText(CellText { cell: *cell, content: ch.to_string() }), cells: vec![*cell] });
        } else {
            for f in frags {
                out.push(FSpan { frag: f, cells: vec![*cell] });
            }
        }
    }
    out
}

