fn jaro(a: &str, b: &str) -> f64 {
    if a == b {
        return 1.0;
    }
    let a_len = a.chars().count();
    let b_len = b.chars().count();
    if a_len == 0 || b_len == 0 {
        return 0.0;
    } else if a_len == 1 && b_len == 1 {
        return if a == b { 1.0 } else { 0.0 };
    }
    let search_range = (a_len.max(b_len) / 2) - 1;
    let mut b_consumed = vec![false; b_len];
    let mut matches = 0.0;
    let mut transpositions = 0.0;
    let mut b_match_index = 0;
    for (i, a_char) in a.chars().enumerate() {
        let min_bound = if i > search_range { i - search_range } else { 0 };
        let max_bound = (b_len - 1).min(i + search_range);
        for (j, b_char) in b.chars().enumerate().take(max_bound + 1) {
            if min_bound <= j && a_char == b_char && !b_consumed[j] {
                b_consumed[j] = true;
                matches += 1.0;
                if j < b_match_index {
                    transpositions += 1.0;
                }
                b_match_index = j;
                break;
            }
        }
    }
    if matches == 0.0 {
        0.0
    } else {
        (1.0 / 3.0) * ((matches / a_len as f64) + (matches / b_len as f64) + ((matches - transpositions) / matches))
    }
}

fn jaro_winkler(a: &str, b: &str) -> f64 {
    let jd = jaro(a, b);
    let prefix = a.chars().zip(b.chars()).take_while(|(x, y)| x == y).count();
    let jw = jd + (0.1 * prefix as f64 * (1.0 - jd));
    if jw <= 1.0 {
        jw
    } else {
        1.0
    }
}

pub fn did_you_mean<'a>(v: &str, candidates: &[&'a str]) -> Option<&'a str> {
    let mut best: Option<(f64, &'a str)> = None;
    for c in candidates {
        let conf = jaro_winkler(v, c);
        if conf > 0.8 && (best.is_none() || best.unwrap().0 < conf) {
            best = Some((conf, c));
        }
    }
    best.map(|(_, c)| c)
}

pub fn good(s: &str) -> String {
    format!("\x1b[32m{}\x1b[0m", s)
}
