    }
    if let Some(v) = m.value("fill-color") {
        settings.fill_color = v.to_string();
    }
    if let Some(v) = m.value("background") {
        settings.background = v.to_string();
    }
    if let Some(v) = m.value("stroke-color") {
        settings.stroke_color = v.to_string();
    }
    if let Some(v) = m.value("font-size") {
        match v.parse::<u64>() {
            Ok(n) => settings.font_size = n,
