fn positional(bin: &str, m: &mut Matches, arg: &str, sub: Option<&str>, _trailing: bool) {
    if sub.is_none() && m.input.is_none() {
        m.input = Some(arg.to_string());
        return;
    }
    let u = usage(bin, sub, &m.used);
    error_exit(&format!("Found argument '{}' which wasn't expected, or isn't valid in this context", arg), &u);
}

fn help_exit(bin: &str, sub: Option<&str>) -> ! {
    match sub {
        Some(_) => print!("{}", cli::build_help(bin)),
        None => print!("{}", cli::main_help(bin)),
    }
    let _ = std::io::stdout().flush();
    exit(0);
}

fn version_exit(sub: Option<&str>) -> ! {
    match sub {
        Some(_) => println!("build 0.0.1"),
        None => println!("svgbob {}", cli::VERSION),
    }
    let _ = std::io::stdout().flush();
    exit(0);
}

fn help_subcommand(bin: &str, rest: &[String]) -> ! {
    if rest.is_empty() {
        help_exit(bin, None);
    }
    let first = &rest[0];
    let unknown = |name: &str| -> ! {
        eprint!(
            "error: The subcommand '{}' wasn't recognized\n\nUSAGE:\n\t{} help <subcommands>...\n\nFor more information try --help\n",
            name, bin
        );
        exit(1);
    };
    match first.as_str() {
        "build" => {
            if rest.len() > 1 {
                unknown(&rest[1]);
            }
            help_exit(bin, Some("build"));
        }
        "help" => {
            if rest.len() > 1 {
                unknown(&rest[1]);
            }
            print!("{}", cli::help_help(bin));
            exit(0);
        }
        other => unknown(other),
    }
}

fn run_build(m: &Matches) {
    let input = m.value("input").unwrap_or("");
    let outdir = m.value("outdir");
    let input_path = Path::new(input);
    let ext = input_path.extension().map(|e| e.to_string_lossy().to_string()).unwrap_or_else(|| "bob".to_string());
    let dir = if input_path.is_dir() {
        input_path.to_path_buf()
    } else {
        input_path.parent().map(|p| p.to_path_buf()).unwrap_or_default()
    };
    if !dir.exists() {
        println!("[Error]: No such dir name is {} !", dir.display());
        return;
    }
    let outdir = match outdir {
        Some(o) => Path::new(o).to_path_buf(),
        None => dir.clone(),
    };
    if let Err(e) = std::fs::create_dir_all(&outdir) {
        println!("{}", e);
        return;
    }
    let entries = match std::fs::read_dir(&dir) {
        Ok(e) => e,
        Err(e) => {
            println!("{}", e);
            return;
        }
    };
    for entry in entries.flatten() {
        let path = entry.path();
        if !path.is_file() {
            continue;
        }
        match path.extension() {
            Some(e) if e.to_string_lossy() == ext => {}
            _ => continue,
        }
        let stem = path.file_stem().map(|s| s.to_string_lossy().to_string()).unwrap_or_default();
        let out_path = outdir.join(format!("{}.svg", stem));
        println!("{} => {}", path.display(), out_path.display());
        let mut s = String::new();
        match std::fs::File::open(&path) {
            Ok(mut f) => {
                if let Err(e) = f.read_to_string(&mut s) {
                    panic_exit("246:32", &format!("called `Result::unwrap()` on an `Err` value: {:?}", e));
                }
            }
            Err(e) => {
                panic_exit("245:40", &format!("called `Result::unwrap()` on an `Err` value: {:?}", e));
            }
        }
        let svg = buffer::to_svg(&s, &settings::Settings::default());
        if let Err(e) = std::fs::write(&out_path, svg.as_bytes()) {
            panic_exit("249:30", &format!("called `Result::unwrap()` on an `Err` value: {:?}", e));
        }
    }
}

fn main() {
    let raw: Vec<String> = std::env::args_os().map(|a| a.to_string_lossy().to_string()).collect();
    let bin = raw
        .first()
        .map(|a| Path::new(a).file_name().map(|f| f.to_string_lossy().to_string()).unwrap_or_else(|| a.clone()))
        .unwrap_or_else(|| "svgbob".to_string());
    let args: Vec<String> = raw.iter().skip(1).cloned().collect();
    let m = match parse(&bin, &args, None) {
        Parsed::Build(bm) => {
            run_build(&bm);
            let _ = std::io::stdout().flush();
            exit(1);
        }
        Parsed::Main(m) => m,
    };
    let inline = m.occurrences.contains_key("inline");
    let mut bob = String::new();
    if inline {
        match &m.input {
            Some(s) => bob = s.clone(),
            None => panic_exit("84:38", "called `Option::unwrap()` on a `None` value"),
        }
    } else if let Some(file) = &m.input {
        match std::fs::File::open(file) {
            Ok(mut f) => {
                if let Err(e) = f.read_to_string(&mut bob) {
                    panic_exit("88:44", &format!("called `Result::unwrap()` on an `Err` value: {:?}", e));
                }
            }
            Err(e) => {
                eprintln!("Failed to open input file {}: {}", file, e);
                exit(1);
            }
        }
    } else if let Err(e) = std::io::stdin().read_to_string(&mut bob) {
        panic_exit("105:46", &format!("called `Result::unwrap()` on an `Err` value: {:?}", e));
    }

    let mut settings = settings::Settings::default();
    if let Some(v) = m.value("font-family") {
        settings.font_family = v.to_string();
    }
    if let Some(v) = m.value("fill-color") {
        settings.fill_color = v.to_string();
    }
    if let Some(v) = m.value("background") {
        settings.background = v.to_string();
    }
    if let Some(v) = m.value("stroke-color") {
        settings.stroke_color = v.to_string();
    }
    if let Some(v) = m.value("font-size") {
        match v.parse::<u64>() {
            Ok(n) => settings.font_size = n,
            Err(e) => {
                eprintln!("Illegal value for argument font-size: {}", e);
                exit(1);
            }
        }
    }
    if let Some(v) = m.value("stroke-width") {
        match v.parse::<f32>() {
            Ok(n) => settings.stroke_width = n,
            Err(e) => {
                eprintln!("Illegal value for argument stroke-width: {}", e);
                exit(1);
            }
        }
    }
    if let Some(v) = m.value("scale") {
        match v.parse::<f32>() {
            Ok(n) => settings.scale *= n,
            Err(e) => {
                eprintln!("Illegal value for argument scale: {}", e);
                exit(1);
            }
        }
    }
    let svg = buffer::to_svg(&bob, &settings);
    if let Some(file) = m.value("output") {
        if let Err(e) = std::fs::File::create(file).and_then(|mut f| f.write_all(svg.as_bytes())) {
            eprintln!("Failed to write to output file {}: {}", file, e);
            exit(2);
        }
    } else {
        println!("{}", svg);
    }
}
