fn pt_cmp(a: &Point, b: &Point) -> std::cmp::Ordering {
    crate::geom::pcmp(a, b)
}

fn frag_cmp(a: &Fragment, b: &Fragment) -> std::cmp::Ordering {
    use crate::geom::fcmp;
    use std::cmp::Ordering;
    match (a, b) {
        (Fragment::Line(x), Fragment::Line(y)) => pt_cmp(&x.start, &y.start).then(pt_cmp(&x.end, &y.end)),
        (Fragment::Arc(x), Fragment::Arc(y)) => pt_cmp(&x.start, &y.start).then(pt_cmp(&x.end, &y.end)),
        (Fragment::Polygon(x), Fragment::Polygon(y)) => {
            for (p, q) in x.points.iter().zip(y.points.iter()) {
                let o = pt_cmp(p, q);
                if o != Ordering::Equal {
                    return o;
                }
            }
            x.points.len().cmp(&y.points.len())
        }
        (Fragment::Circle(x), Fragment::Circle(y)) => pt_cmp(&x.center, &y.center).then(fcmp(x.radius, y.radius)),
        _ => {
            let (ax1, ay1, ax2, ay2) = crate::tree::bounds(a);
            let (bx1, by1, bx2, by2) = crate::tree::bounds(b);
            fcmp(ay1, by1)
                .then(fcmp(ax1, bx1))
                .then(fcmp(ay2, by2))
                .then(fcmp(ax2, bx2))
                .then(variant(a).cmp(&variant(b)))
        }
    }
}

