import sys, itertools
from cmp import compare
from grid import grid, POS
from concurrent.futures import ThreadPoolExecutor
CH="-_|/\\+.,'`*oO#<>^vV()~=:!X"
UNI="─│┌┐└┘├┤┬┴┼═║╔╗╚╝╭╮╰╯╱╲╳●○◆▲▼►◄┄┆█▪"
jobs=[(c,p,n) for c in CH for p in POS for n in UNI]
def f(j):
    c,p,n=j
    return j, compare(grid(c,[(p,n)]), show=False)
bad={}
with ThreadPoolExecutor(48) as ex:
    for (c,p,n),ok in ex.map(f,jobs,chunksize=16):
